def is_cactus(g):
    def has_loops(u, p=None):
        return any((u, v) in g for v in (g[u] if p is None else g[u][p]) if v != u)

    def is_cactus_core(u, seen):
        if u in seen: return False
        seen.add(u)
        for v in g[u]:
            if has_loops(v, u) or is_cactus_core(v, seen):
                return False
        return True

    return all(is_cactus_core(u, set()) for u in g)

