        for L, R in combinations(range(len(shortest_distances)), 2):
            if L >= R:
                continue  # skip since L >= R because there is no way to specify lengths of consecutive edges
            match_shortest_L = shortest_distances[L] == shortest_distances[R]
            match_shortest_R = match_shortest_L
            intersected_edges = len(set(g[u][v] for u, v in combinations(L + R, 2) if g[u][v] in set(L + R)))
            L_subset = intersected_edges > 0 and g[u][v] in set(L)
            R_subset = intersected_edges > 0 and g[u][v] in set(R)
