def max_odd_proper_prefix(l):
    n = len(s)
    k = l + 1
    memo = [(0] * (n + 1))
    for i, c in enumerate(s, 1):
        k = ord(c) - ord('a') + 1
        memo[i] = memo[i - 1] + k

    prefix = 0
    dp = defaultdict(int)
    for i in range(1, n + 1):
        if memo[i] > 0:
            prefix += memo[i] - 1
        if memo[i - n] >= 1 and i - n + 1 in dp:
            j = i - n + 1
            if ((j - 1) // prefix) % 2 == 0:
                dp[i] = dp[j] + 1
        elif (prefix * (prefix + 1) // 2 + j // prefix - ((j - 1) // prefix) * 2) % 2 == 1 and i - n + 1 in dp:
            dp[i] = dp[j] + 1

    ans = [-1] * n
    for i, p in sorted(dp.items()):
        if i - n // k + 1 >= 0 and p > ans[i - n // k + 1]:
            ans[i - n // k + 1] = p
