def find_area(prefix_sum, dp, i, j, value):
    Mi = -100
    Mj = -100
    Mi, Mj = max(Mi, value - prefix_sum[i - 1][j - 1] + prefix_sum[i - 1][j]), max(Mj, value - prefix_sum[i - 1][j - 1] + prefix_sum[i][j - 1] - prefix_sum[i - 1][j - 1])
    if dp[i][j]:
        Mi, Mj = max(Mi, value), max(Mj, value)

    for k in range(i - 1, -1, -1):
        if dp[k][j]:
            Mi = max(Mi, value - prefix_sum[k][j - 1] + prefix_sum[k][j])
            break
    for k in range(j - 1, -1, -1):
        if dp[i][k]:
            Mj = max(Mj, value - prefix_sum[i - 1][k] + prefix_sum[i - 1][k] - prefix_sum[i - 1][j - 1])

    return Mi * Mj

