def find_odirects(cities, roads, s, t):
    neighbors = defaultdict(set)
    for i, v in enumerate(roads):
        a, b = v
        neighbors[a].add(b)
        neighbors[b].add(a)

    def dfs(start):
        stack = [(start, None)]
        while stack:
            current, parent = stack.pop()
            for neighbor in neighbors[current]:
                if neighbor == parent:
                    continue
                stack.append((neighbor, current))
                yield neighbor, current, False
            yield current, parent, True if current == t else False

    dfs_s = dfs(s)
    dfs_t = dfs(t)
    odirect = list()

    for neighbor, top, back in dfs_s:
        for i in range(len(roads)):
            if roads[i][0] == top:
                if not back and (i, neighbor) not in odirect:
                    odirect.append((i, neighbor))
            elif roads[i][1] == top:
                if back and (neighbor, i) not in odirect:
                    odirect.append((neighbor, i))

    for neighbor, top, back in dfs_t:
        for i in range(len(roads)):
            if roads[i][0] == top:
                if not back and (i, neighbor) not in odirect:
                    odirect.append((i, neighbor))
            elif roads[i][1] == top:
                if back and (neighbor, i) not in odirect:
