from collections import deque

def find_contamination_rows(lattice_lines):
    contamination_rows = []
    for col in range(len(lattice_lines[0])):
        if any(row[col] == '1' for row in lattice_lines):
            contamination_rows.append(col)
    return contamination_rows

def find_contamination_columns(lattice_lines):
    contamination_columns = [col for col in range(len(lattice_lines[0])) if any(row[col] == '1' for row in lattice_lines)]
    return contamination_columns

def bfs_contamination(lattice_lines, start_row, start_col, end_row, end_col):
    contamination_count = 0
    contamination_is_found = False
    contamination_stack = deque([(start_row, start_col)])

    while contamination_stack:
        current_row, current_col = contamination_stack.popleft()
        if current_row == end_row and current_col == end_col:
            contamination_is_found = True
            break
        if lattice_lines[current_row][current_col] == '1':
            lattice_lines[current_row][current_col] = '0'  # Mark as visited
            if current_row - 1 >= 0:
                buffer_row = current_row - 1
                buffer_col = current_col
                while buffer_row >= 0 and lattice_lines[buffer_row][buffer_col] != '0':
                    lattice_lines[buffer_row][buffer_col] = '0'
                    buffer_row -= 1
                    contamination_count += 1
            if current_row + 1 < len(lattice_lines):
                buffer_row = current_row + 1
                buffer_col = current_col
                while buffer_row < len(lattice_lines) and lattice_lines[buffer_row][buffer_col] != '0':
                    lattice_lines[buffer_row][buffer_col] = '0'
                    buffer_row += 1
                    contamination_count += 1
            if current_col - 1 >= 0:
                buffer_row = current_row
                buffer_col = current_col - 1
                while buffer_col >= 0 and lattice_lines[buffer_row][buffer_col] != '0':
                    lattice_lines[buffer_row][buffer_col] = '0'
                    buffer_col -= 1
                    contamination_count += 1
            if current_col + 1 < len(lattice_lines[0]):
                buffer_row = current_row
                buffer_col = current_col + 1
                while buffer_col < len(lattice_lines[0]) and lattice_lines[buffer_row][buffer_col] != '0':
                    lattice_lines[buffer_row][buffer_col] = '0'
                    buffer_col += 1
                    contamination_count += 1
        contamination_stack.append((current_row, current_col))

    return contamination_count, contamination_is_found

def detect_zombie_lair(lattice_lines):
    contamination_rows = find_contamination_rows(lattice_lines)
    contamination_columns = find_contamination_columns(lattice_lines)

    if not contamination_rows or not contamination_columns:
        return "No contours detected."

    system_zero = False
    for row in lattice_lines:
        if '0' in row:
            system_zero = True
            break
    if not system_zero:
        return "System Zero detected. Not a zombie lair."

    lair_found = False
    discovered_contours = set()
    for row0, col0, row1, col1 in ((row, col, row + 1, col), (row, col, row, col - 1), (row, col - 1, row, col), (row1, col0, row1, col1)):
        if (row0 not in contamination_rows and col0 in contamination_columns) or (col0 not in contamination_rows and row0 in contamination_columns):
            zero_count, found = bfs_contamination(lattice_lines, row0, col0, row1, col1)
            discovered_contours.add((row0, col0, zero_count, found))
            lair_found = found

    if not lair_found:
        return "No valid contours found for the Zombie Lair."

    contour_coordinates = []
    for contour in discovered_contours:
        contour_coordinates.append((contour[1], contour[0]))

    # [2: system_zero - 1]
    contour_coordinates.append((contour_coordinates[0][1], contour_coordinates[-1][0]))
    contour_coordinates.sort(key=lambda x: (x[1], x[0]))
    contour_coordinates = list(dict.fromkeys(contour_coordinates))  # Remove duplicates
    contour_coordinates.sort(key=lambda x: x[0])  # Sort lexicographically

    return str(len(contour_coordinates) - 1) + "\n" + "\n".join(map(str, contour_coordinates))
