    ship_dirs = {'N': (-1, 0), 'S': [1, 0], 'E': (0, 1), 'W': [0, -1]}
    wind_dirs = {'N': 'NESW', 'S': 'NSEW', 'E': 'NESW', 'W': 'NESW'}

