        ship_pos.add((x, y+1))
        ship_pos.add((x, y-1))
        ship_pos.add((x+1, y))
        ship_pos.add((x-1, y))

    for direct in wind_dirs[wind_info]:
        ship_delta = [ship_pos[0]]
        for _ in range(2):
