                    nx, ny = px + dx, py + dy
                    ship_nxt.add((nx, ny))
                    ship_nxt.add((nx, y+1))
                    ship_nxt.add((x+1, y))
                    ship_nxt.add((x-1, y))
                    ship_nxt.add((x, y-1))
            ship_delta = ship_nxt

    # Check 4-connected path from each ship position
    for ship_pos in ship_pos:
        x, y = ship_pos
        ships = set()
        ships.update({ship_pos})

        arrived = set()
        day = 0 if (wind_info in {'N', 'S'}) else 1
        while not arrived and (x, y) not in arrived and day <= 100:
            if wind_info in {'C'}:
