                    wind_pos.add((nx, ny+1))
                    wind_pos.add((nx, y+1))
                    wind_add.update({(nx, ny+1)})
                    wind_add.update({(nx, y+1)})
                    wind_dirs.add((wind_dirs, wind_dirs[direct]))

                ships.add(smallest_sea())
