from typing import List

def calculate_value(m: int, n: int, sequence: List[int]) -> int:
    prefix_sum = [0] * (n + 1)
    for i, value in enumerate(sequence):
        prefix_sum[i + 1] = prefix_sum[i] + value

    maximum = 0
    for min_val in range(1, n + 1):
        for max_val in range(min_val, n + 1):
            if min_val * max_val > n:
                break
            current_value = prefix_sum[max_val] - prefix_sum[min_val - 1] - (
                prefix_sum[max_val + 1] - prefix_sum[min_val]
            )

            consecutive_values = max_val - min_val
            for i in range(min_val, max(min_val, max_val - 1) + 1):
                for j in range(i + 1, max_val + 1):
                    if i + 1 < j:
                        current_value -= (
                            max_value := max(sequence[i], sequence[j]) - min_value
                        )
                    else:
                        current_value -= min_value

            maximum = max(maximum, current_value)

    return maximum

