import sys

MOD = 10**9 + 7

class EulerTotient:
    def __init__(self, max_val):
        self.prime_factors = [i for i in range(max_val + 1) if is_prime(i)]
        self.powers = [1] * (max_val + 1)
        for i in self.prime_factors:
            self.update_product_factors(i)

    def update_product_factors(self, root):
        for new_root in self.prime_factors:
            if root + new_root > max_val:
                break
            self.powers[root + new_root] = self.powers[root + new_root] * self.powers[root] % MOD

    def tic(self):
        return (self.powers[root] if root in self.powers else 0) % MOD

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, n):
        if n % i == 0:
            return False
    return True

if __name__ == "__main__":
