        if query == "MULTIPLY":
            l, r, x = map(int, args)
            euler_totient.powers[l] = euler_totient.powers[l] * x % MOD
            euler_totient.powers[r + 1] = euler_totient.powers[r + 1] * x % MOD
        elif query == "TOTIENT":
            l, r = map(int, args)
