from typing import List

def assemble_scheme(points: List[List[int]]) -> List[List[int]]:
    sparks = set()
    max_x = max(point[0] for point in points)
    max_y = max(point[1] for point in points)

    for y in range(1, max_y + 1):
        if y in (1, max_y):
            for x in range(1, max_x + 1):
                sparks.add((x, y))
        else:
            for x in range(1, max_x + 1):
                if y > points[0][1] and points[0][1] >= y:
                    sparks.add((x, y))
                elif y < points[-1][1] and points[-1][1] <= y:
                    sparks.add((x, y))

    horizontal_wires = []
    vertical_wires = []

    # Place horizontal wires
    for y in range(1, max_y + 1):
        curve_points = [(x, y) for x in range(1, max_x + 1) if y < points[0][1] or points[-1][1] < y]
        if curve_points:
            horizontal_wires.append((1, y, 1, y))
            if points[0][1] < y:
                horizontal_wires.append((1, y, max_x, y))
            if points[-1][1] > y:
                horizontal_wires.append((1, y, max_x, y))
            if points[0][1] > y:
                horizontal_wires.append((1, y, points[0][0], y))
            if points[-1][1] < y:
                horizontal_wires.append((1, y, points[-1][0], y))

    # Place vertical wires
    for x in range(1, max_x + 1):
        curve_points = [(x, y) for y in range(1, max_y + 1) if x < points[0][0] or points[-1][0] < x]
        if curve_points:
            vertical_wires.append((x, 1, x, 1))
            if points[0][0] < x:
                vertical_wires.append((x, 1, x, max_y))
            if points[-1][0] > x:
                vertical_wires.append((x, 1, x, max_y))
            if points[0][0] > x:
                vertical_wires.append((x, 1, x, points[0][1]))
            if points[-1][0] < x:
                vertical_wires.append((x, 1, x, points[-1][1]))

    return horizontal_wires + vertical_wires

