def solve(n, k):
    k2 = k * k
    dp = [1] * n  # dp[i] stores the number of solutions for one ice piece
    dp[0] = 0  # no solution

    for i in range(1, n):
        if dp[i-1] == 0:
            dp[i] = 0
        else:
            dp[i] = dp[i-1]

        if i + k2 > n:
            dp[i] = 0
        else:
            dp[i] += dp[i+k2-1]

        if i + 3*k2 > n:
            dp[i] = 0
        else:
            dp[i] += dp[i+3*k2-1]

    for i in range(n):
        dp[i] = dp[i] * (k2 - k2 // (k+1)) // k  # Estimate number of squares containing `i` pieces

    return dp

