import bisect

def array_composition_query(n, composition, query_count, queries):
    results = []
    for query_m, query_y in queries:
        start, end, count = 0, n, 0
        for m in query_m:
            index = bisect.bisect_left(composition, m)
            if index < end:
                start = index
            end = min(end, index + 1)
            if composition[start] == query_y:
                count += start + 1 - start
            else:
                count += start
