from collections import deque
from typing import List

def check_port_validity(board: List[List[str]], mrow, mcol, wind_list: List[str]) -> bool:
    """
    Determines if the ship can reach the port with available food supplies.
    """
    directions = {'N': (-1, 0), 'S': (1, 0), 'E': (0, 1), 'W': (0, -1)}
    max_day_of_food = {maze[x][y]: day for x, y, day in wind_list if maze[x][y] == 'M'}

    for day in range(1, len(wind_list) + 1):
        # Get the food capacities from the wind
        working_day_food = max_day_of_food.get((mrow, mcol), day)

        # Update the queue based on the wind's direction
        if wind_list[day - 1] in directions:
            new_mrow, new_mcol = mrow + directions[wind_list[day - 1]][0], mcol + directions[wind_list[day - 1]][1]
            if new_mrow < 0 or new_mrow >= len(board) or new_mcol < 0 or new_mcol >= len(board[0]) or board[new_mrow][new_mcol] in {'N', 'S'}:
                return False
        else:
            new_mrow, new_mcol = mrow, mcol if board[mrow][mcol] == '.' else mrow

        # Check if we have reached the port
        if (new_mrow, new_mcol) == (len(board) - 1, len(board[0]) - 1):
            return True and working_day_food >= max_day_of_food[(mrow, mcol)] - day + 1

        # Otherwise, explore the new position
        mrow, mcol = new_mrow, new_mcol

    return False

def find_min_days(board: List[List[str]], wind_list: List[str]) -> int:
    """
    Calculates the minimum number of days to reach the port, if possible.
    """
    directed_distance = len(board) * len(board[0])

    # If the last row or column is L (land)
    for i in range(len(board[0])):
        if board[len(board) - 1][i] == 'L':
            return directed_distance if board[len(board) - 1][i + 1: len(board) - 1] == 'S' else -1

    # If the last row or column is S (sea)
    for i in range(len(board)):
        if board[i][-1] == 'L':
            return directed_distance if board[i][0: len(board[i]) - 1] == 'S' else -1

    # Initialize the BFS search
    q = deque([[mrow, mcol, 0]])
    visited = set()
    visited.add((mrow, mcol, 0))
    update_moron = set()

    while q:
        mrow, mcol, day = q.popleft()
        if mrow, mcol, day == len(wind_list) - 1:
            return day + 1
        if board[mrow][mcol] in {'M', 'P'}:
            update_moron.add((mrow, mcol, day + 1))


        for direction in {'N', 'S', 'E', 'W'}:
            next_drow, next_dcol = mrow + directions[direction][0], mcol + directions[direction][1]
            if (next_drow, next_dcol) in board and board[next_drow][next_dcol] in {'S', 'P'}:
                q.append([next_drow, next_dcol, day + 1])
                visited.add((next_drow, next_dcol, day + 1))

    return -1

