            if dp[i][j] == dp[n-1][m-1] and a[i][j] != dp[n-1][m-1]:
                rows = min(rows, i)      
                cols = max(cols, j)

    for i in range(n-1, -1, -1):
        if dp[i][m-1] == dp[n-1][m-1] and a[i][m-1] != dp[n-1][m-1]:
            rows = max(rows, i)

    for j in range(m-1, -1, -1):
        if dp[n-1][j] == dp[n-1][m-1] and a[n-1][j] != dp[n-1][m-1]:
            cols = min(cols, j)

    area = (rows - cols + 1) * (m - cols + 1)
    best = max(best, area)

    for i in range(n):
        for j in range(m):
            if dp[i][j] == dp[n-1][m-1] or a[i][j] != dp[n-1][m-1]:
                dp[i][j] = dp[n-1][m-1]
                if i+1 < n:
                    dp[i+1][j] += a[i+1][j]- a[i][j]
                    if dp[i+1][j] < dp[i][j]:
                        dp[i+1][j] = dp[i][j]
                if j+1 < m:
                    dp[i][j+1] += a[i][j+1] - a[i][j]
                    if dp[i][j+1] < dp[i][j]:
                        dp[i][j+1] = dp[i][j]
    rows = [float('-inf')]
    cols = [float('-inf')]
    for i in range(n-1, -1, -1):
        if dp[i][m-1] == dp[n-1][m-1] or a[i][m-1] != dp[n-1][m-1]:
            rows = max(rows, i)      
    for j in range(m-1, -1, -1):
        if dp[n-1][j] == dp[n-1][m-1] or a[n-1][j] != dp[n-1][m-1]:
            cols = min(cols, j)

    temp = (cols - rows + 1) * (m - rows + 1)
    best = max(best, temp)

    return best

# Example usage:
n = 3
m = 3
a = [[1,3,1],[4,5,6],[2,6,1]]
result = find_largest_inhomogeneous_submatrix(n, m, a)
