    """Compute the binomial coefficient, nCr."""
    if r < 0 or n < r:
        return 0
    r = min(r, n - r)  # Take advantage of symmetry
    if r == 0:
        return 1
    numer = reduce(lcm, range(n, n - r, -1))
    denom = reduce(lcm, range(1, r + 1))
    return numer // denom

