from math import gcd
from functools import lru_cache

class EulerTotient:
    def multiply(self, queries):
        a = [0] + list(map(int, input().split()))
        n = len(a)

        @lru_cache(None)
        def gcd_of_subsets(subset):
            if len(subset) == 0:
                return 1
            if len(subset) == 1:
                return a[1]
            return a[1] * gcd(subset[0], gcd_of_subsets(subset[1:]))

        @lru_cache(None)
        def totient_of_subset(subset):
            if len(subset) == 0:
                return 1
            if len(subset) == 1:
                return 1
            common_gcd = a[1] * gcd(subset[0], a[1])
            gcd_of_values = gcd_of_subsets(subset)
            return gcd_of_values * (a[1] - (1 if common_gcd == a[1] else 0) + 1) - gcd_of_values

        total_sums = 0
        for query in range(1, len(queries), 2):
            queries[query], queries[query+1] = queries[query+1], queries[query]
        del queries[1]
        queries = [query // 2 for query in queries]  # Each query is for a pair (i, j)

        for query in queries:
            l, r = query, query + 1
            left_half_values = set()
            for i in range(1, n+1):
                value = a[i]
                if l <= i <= r:
                    left_half_values.add(value)
            right_half_values = set()
            for i in range(r + 1, n + 1):
                value = a[i]
                if l <= i <= r:
                    right_half_values.add(value)

            total_sums = (total_sums + (a[l] * a[r] - (totient_of_subset(left_half_values) * totient_of_subset(right_half_values)))) % 1000000007
            result = (a[l] * a[r] - totient_of_subset(left_half_values * right_half_values)) % 1000000007

        print(result)

if __name__ == "__main__":
    n, q = map(int, input().split())
    EulerTotient().multiplication(q)
