from collections import defaultdict

def find_pairs_with_desert_edges(n, m, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    cycles = []
    flip_cycles = []

    def dfs(node, parent):
        if len(graph[node]) == 1 and node != 1:
            if node in cycles:
                cycles.remove(node)
                flip_cycles.append(node)
            else:
                cycles.append(node)

        for neighbor in graph[node]:
            if neighbor != parent:
                dfs(neighbor, node)

    dfs(1, None)
    cycles.sort()

    for cycle in cycles:
        prev = cycle - 1
        while prev in graph and len(graph[prev]) > 1:
            graph[prev] = [prev] + graph[prev][1:]
        neighbor_in_cycle = graph[prev].pop(0)
        graph[neighbor_in_cycle].remove(prev)
        if neighbor_in_cycle not in flip_cycles:
            flip_cycles.append(neighbor_in_cycle)

    if cycles:
        flip_cycles = cycles
    elif flip_cycles:
        flips = flip_cycles.copy()
        for edge in edges:
            if edge not in flip_cycles:
                flips.append(edge)
            n_cyc_turns = (n - 1) - (len(flip_cycles) - 1)
            if n_cyc_turns != flips[-1]:
                flips.append(n_cyc_turns + 1)
            flips.sort()
        flip_cycles = flips
    else:
        flip_cycles = [-1]

    pairs_with_desert_edges = 0
    for i in range(len(flip_cycles)):
        j = (i + len(flip_cycles)) % len(flip_cycles)
        if flip_cycles[i] == 1:
            pairs_with_desert_edges += (j + 1) * (j + 2) // 2
    return pairs_with_desert_edges

# Example usage
n, m = 5, 6
edges = [(1, 2), (2, 3), (3, 4), (4, 5), (5, 1), (2, 4)]
print(find_pairs_with_desert_edges(n, m, edges))
