import collections

def count_inadequate_substrings(s):
    inadequate = [str(i) for i in range(1, 10)] + ["0" * i for i in range(10, 20)]
    inadequate_index = {x: i for i, x in enumerate(inadequate)}

    count = 0
    for i, char in enumerate(s):
        if char in inadequate_index:
            count += inadequate_index[char]
        else:
            count += inadequate_index.get(int(char), 0)

    return count

# Example usage
s = "4021"
print(count_inadequate_substrings(s))  # Output: 6
